function CheckboxField({ id, labelHTML, helperText, errorText, required }) {
  const wrapper = document.createElement("div");
  wrapper.className = "form-field";
  wrapper.dataset.field = id;

  // <label> wraps both the hidden input and the custom visual + text
  const label = document.createElement("label");
  label.className = "form-field__control";
  label.htmlFor = id;

  const input = document.createElement("input");
  input.type = "checkbox";
  input.id = id;
  input.name = id;
  if (required) {
    input.required = true;
    input.setAttribute("aria-required", "true");
  }
  input.setAttribute("aria-describedby", `${id}-helper ${id}-error`);

  const visual = document.createElement("span");
  visual.className = "form-field__checkbox-visual";
  visual.setAttribute("aria-hidden", "true");

  const labelSpan = document.createElement("span");
  labelSpan.className = "form-field__label-text";
  labelSpan.innerHTML = labelHTML;

  label.appendChild(input);
  label.appendChild(visual);
  label.appendChild(labelSpan);

  const helper = document.createElement("p");
  helper.className = "form-field__helper";
  helper.id = `${id}-helper`;
  helper.textContent = helperText;

  const error = document.createElement("p");
  error.className = "form-field__error";
  error.id = `${id}-error`;
  error.setAttribute("aria-live", "polite");
  error.innerHTML = `
    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" aria-hidden="true">
      <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm1 15h-2v-2h2v2zm0-4h-2V7h2v6z"/>
    </svg>
    ${errorText}`;

  wrapper.appendChild(label);
  wrapper.appendChild(helper);
  wrapper.appendChild(error);

  return wrapper;
}

function SubmitButton({ text }) {
  const btn = document.createElement("button");
  btn.type = "submit";
  btn.className = "btn-submit";
  btn.innerHTML = `
    ${text}
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" aria-hidden="true" fill="currentColor">
      <path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6z"/>
    </svg>`;
  return btn;
}

function SuccessMessage() {
  const div = document.createElement("div");
  div.className = "success-message";
  div.setAttribute("role", "status");
  div.innerHTML = `
    <div class="success-message__icon" aria-hidden="true">
      <svg xmlns="http://www.w3.org/2000/svg" width="28" height="28" viewBox="0 0 24 24">
        <path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/>
      </svg>
    </div>
    <p class="success-message__title">You're all set!</p>
    <p class="success-message__body">Thanks for agreeing to our Terms of Use. You can now continue using the service.</p>`;
  return div;
}

function ConsentForm() {
  const card = document.createElement("div");
  card.className = "card";

  // Icon
  const iconWrap = document.createElement("div");
  iconWrap.className = "card__icon";
  iconWrap.setAttribute("aria-hidden", "true");
  iconWrap.innerHTML = `
    <svg xmlns="http://www.w3.org/2000/svg" width="26" height="26" viewBox="0 0 24 24">
      <path d="M14 2H6c-1.1 0-2 .9-2 2v16c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V8l-6-6zm-1 7V3.5L18.5 9H13zm-5 8v-2h8v2H8zm0-4v-2h8v2H8z"/>
    </svg>`;

  const heading = document.createElement("h1");
  heading.className = "card__heading";
  heading.textContent = "Terms of Use";

  const subheading = document.createElement("p");
  subheading.className = "card__subheading";
  subheading.textContent =
    "Please read and accept our terms before continuing. Your agreement lets us provide you with the best experience.";

  // Live region for submit feedback
  const liveRegion = document.createElement("p");
  liveRegion.className = "sr-only";
  liveRegion.setAttribute("aria-live", "polite");
  liveRegion.setAttribute("aria-atomic", "true");

  // Form
  const form = document.createElement("form");
  form.className = "consent-form";
  form.noValidate = true;
  form.setAttribute("aria-label", "Terms of use agreement");

  const checkboxField = CheckboxField({
    id: "consent",
    labelHTML: `I have read and agree to the <a href="#terms" aria-label="Terms of Use (opens in same page)">Terms of Use</a>`,
    helperText:
      "You must accept the Terms of Use to create an account and use our services.",
    errorText: "Please accept the Terms of Use to continue.",
    required: true,
  });

  const submitBtn = SubmitButton({ text: "Continue" });
  const successMsg = SuccessMessage();

  form.appendChild(checkboxField);
  form.appendChild(submitBtn);

  form.addEventListener("submit", (e) => {
    e.preventDefault();
    const checkbox = form.querySelector("#consent");
    const fieldWrapper = form.querySelector('[data-field="consent"]');

    if (!checkbox.checked) {
      // Mark invalid
      fieldWrapper.classList.add("form-field--invalid");
      checkbox.setAttribute("aria-invalid", "true");
