      requestAnimationFrame(() => {
        liveRegion.textContent = "Error: Please accept the Terms of Use to continue.";
      });
      // Move focus to the checkbox so the error is associated
      checkbox.focus();
      return;
    }

    // Clear invalid state
    fieldWrapper.classList.remove("form-field--invalid");
    checkbox.removeAttribute("aria-invalid");
    liveRegion.textContent = "";

    // Show success
    form.style.display = "none";
    successMsg.style.display = "flex";
    liveRegion.textContent = "Success! You have agreed to the Terms of Use.";
  });

  // Clear error as soon as the user checks the box
  form.querySelector("#consent").addEventListener("change", function () {
    if (this.checked) {
      const fieldWrapper = form.querySelector('[data-field="consent"]');
      fieldWrapper.classList.remove("form-field--invalid");
      this.removeAttribute("aria-invalid");
      liveRegion.textContent = "";
    }
  });

  card.appendChild(iconWrap);
  card.appendChild(heading);
  card.appendChild(subheading);
  card.appendChild(form);
  card.appendChild(successMsg);
  card.appendChild(liveRegion);

  return card;
}

// Mount
(function mount() {
  const root = document.getElementById("root");
  root.appendChild(ConsentForm());
})();
